public class QuantityReview {
    public static void main(String[] args) {
        int[] requested = {2, 0, 4};
        int accepted = 0;
        for (int quantity : requested) {
            if (quantity > 0 && quantity <= 3) {
                accepted += quantity;
            }
        }
        System.out.println("Accepted quantity: " + accepted);
    }
}

public class BorrowRequest {
    private final String item;
    private final int quantity;
    private boolean closed;
    public BorrowRequest(String item, int quantity) {
        if (item == null || item.isBlank() || quantity <= 0) {
            throw new IllegalArgumentException("Invalid request");
        }
        this.item = item; this.quantity = quantity;
    }
    public void close() {
        if (closed) throw new IllegalStateException("Already closed");
        closed = true;
    }
    public String describe() { return item + ": " + quantity; }
    public static void main(String[] args) {
        BorrowRequest request = new BorrowRequest("Camera", 2);
        System.out.println(request.describe());
        request.close();
    }
}

