type RequestState = 'OPEN' | 'CLOSED';
interface SharedRequest {
  id: number; title: string; quantity: number; state: RequestState;
}
function remaining(items: ReadonlyArray<SharedRequest>): number {
  return items.filter(item => item.state === 'OPEN')
    .reduce((sum, item) => sum + item.quantity, 0);
}
