def open_quantity(records):
    total = 0
    for record in records:
        if record['state'] == 'OPEN':
            total += record['quantity']
    return total

requests = [
    {'title': '相机', 'quantity': 2, 'state': 'OPEN'},
    {'title': '投影仪', 'quantity': 1, 'state': 'CLOSED'},
]
assert open_quantity(requests) == 2
assert open_quantity([]) == 0
print(open_quantity(requests))

def inspect_proposal(proposal, allowed_ids):
    if not isinstance(proposal, dict):
        raise ValueError('结果必须是对象')
    identifiers = proposal.get('source_ids')
    if not isinstance(identifiers, list) or not identifiers:
        raise ValueError('需要提供来源编号')
    if any(value not in allowed_ids for value in identifiers):
        raise ValueError('包含未授权或不存在的来源')
    return {'accepted': True, 'source_ids': identifiers}

sample = {'source_ids': ['notice-17']}
print(inspect_proposal(sample, {'notice-17', 'notice-18'}))
